/* ------------------------------------------------------------------------- */
/* Migration 27: Atualização completa de produtos e preços do mercado        */
/* Fonte: exp_cadprodutos.cds / produtos1.csv extraído em 01/10/2026         */
/* Atualiza 4759 itens com preços vigentes e vincula categorias               */
/* Idempotente: pode ser executado múltiplas vezes sem erros                 */
/* ------------------------------------------------------------------------- */

USE HorusPdv;
GO

SET NOCOUNT ON;
GO

IF OBJECT_ID('tempdb..#ProdutosUpdateTemp') IS NOT NULL
    DROP TABLE #ProdutosUpdateTemp;

CREATE TABLE #ProdutosUpdateTemp
(
    ProductCode NVARCHAR(80) NOT NULL,
    ProductName NVARCHAR(180) NOT NULL,
    Gtin NVARCHAR(14) NOT NULL,
    Unidade NVARCHAR(6) NOT NULL,
    ProductUnitPrice DECIMAL(15, 4) NOT NULL,
    ProductSalePrice DECIMAL(15, 4) NOT NULL,
    Ncm CHAR(8) NOT NULL,
    Cest CHAR(7) NULL,
    Cfop CHAR(4) NOT NULL,
    CsosnIcms NVARCHAR(4) NOT NULL,
    CstPis NVARCHAR(3) NOT NULL,
    CstCofins NVARCHAR(3) NOT NULL,
    CategoriaId NVARCHAR(40) NULL
);
GO

GO

GO

GO

GO

GO

GO

GO

GO

GO

GO

DECLARE @EmpresasDestino TABLE (CompanyId NVARCHAR(40));
SELECT Id FROM Empresas
UNION
SELECT N'empresa-principal';

MERGE INTO Produtos AS target
USING (
    SELECT e.CompanyId, t.ProductCode, t.ProductName, t.Gtin, t.Unidade, t.ProductUnitPrice, t.ProductSalePrice,
           t.Ncm, t.Cest, t.Cfop, t.CsosnIcms, t.CstPis, t.CstCofins, t.CategoriaId
    FROM #ProdutosUpdateTemp t
    CROSS JOIN @EmpresasDestino e
) AS source
ON target.CompanyId = source.CompanyId AND target.ProductCode = source.ProductCode
WHEN MATCHED THEN
    UPDATE SET 
        target.ProductName = source.ProductName,
        target.Gtin = CASE WHEN source.Gtin <> N'SEM GTIN' AND source.Gtin IS NOT NULL THEN source.Gtin ELSE target.Gtin END,
        target.UnidadeComercial = source.Unidade,
        target.UnidadeTributavel = source.Unidade,
        target.ProductSalePrice = source.ProductSalePrice,
        target.ProductUnitPrice = CASE WHEN source.ProductUnitPrice > 0 THEN source.ProductUnitPrice ELSE target.ProductUnitPrice END,
        target.CategoriaId = COALESCE(target.CategoriaId, source.CategoriaId),
        target.Ncm = CASE WHEN source.Ncm <> '00000000' THEN source.Ncm ELSE target.Ncm END,
        target.Cest = COALESCE(source.Cest, target.Cest),
        target.Cfop = CASE WHEN source.Cfop <> '5102' THEN source.Cfop ELSE target.Cfop END,
        target.CsosnIcms = COALESCE(source.CsosnIcms, target.CsosnIcms),
        target.CstPis = COALESCE(source.CstPis, target.CstPis),
        target.CstCofins = COALESCE(source.CstCofins, target.CstCofins)
WHEN NOT MATCHED THEN
    INSERT
    (
        Id,
        CompanyId,
        ProductImageUrl,
        ProductImageName,
        ProductName,
        ProductCode,
        ProductSupplier,
        SupplierId,
        ProductDescription,
        ProductQnt,
        ProductUnitPrice,
        ProductSalePrice,
        TotalPriceOnProduct,
        MargemDesejadaPercentual,
        Ncm,
        Cest,
        Cfop,
        OrigemMercadoria,
        UnidadeComercial,
        UnidadeTributavel,
        Gtin,
        CsosnIcms,
        CstIcms,
        AliquotaIcms,
        CstPis,
        CstCofins,
        CstIbsCbs,
        CClassTrib,
        CategoriaId
    )
    VALUES
    (
        LOWER(NEWID()),
        source.CompanyId,
        N'',
        N'',
        source.ProductName,
        source.ProductCode,
        N'Atualização CDS 01/10/2026',
        NULL,
        N'Atualizado a partir de produtos1.csv em 01/10/2026',
        100.0000,
        source.ProductUnitPrice,
        source.ProductSalePrice,
        0.00,
        NULL,
        source.Ncm,
        source.Cest,
        source.Cfop,
        0,
        source.Unidade,
        source.Unidade,
        source.Gtin,
        source.CsosnIcms,
        NULL,
        0.0000,
        source.CstPis,
        source.CstCofins,
        NULL,
        NULL,
        source.CategoriaId
    );

DROP TABLE #ProdutosUpdateTemp;
GO
